    },
    "cold_reviewer_clarity": {
      "status": "review",
      "note": "A reviewer could reconstruct factual sequences and supervisor rationales from the record, but critical evidentiary files are documented as missing: the DRAD file with medical records (referenced as 'does not contain'), FMLA request files, and the leave record itself, all of which are essential to independent verification of accommodation and leave decisions."
    },
    "accountability_support": {
      "status": "review",
      "note": "The record supports some conclusions with specifics (S1A's February 2018 emails on telework hardship, S1B's testimony on coverage strain) but lacks supporting documentation for contested facts (Complainant's medical documentation, actual leave balance records, FMLA form completeness assessments, and the content of the alleged HR voicemail recording)."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "Chronology is well-documented: position start (November 2016), first accommodation request (December 21, 2017), multiple decision dates (February 2018, June 7, 2018, August 20, 2018), supervisor transitions, and leave incidents are sequenced with specific dates and intervals clearly marked."
    }
  },
  "remediation_note": "To achieve full compliance, the record must include or reference the missing DRAD file (with medical documentation), FMLA forms and medical evidence, and leave balance records to permit independent verification of accommodation and leave denials. The final discrimination determination must be explicitly documented to show how evidence was weighed against statutory standards.",
  "finding": {
    "ai_function": "narrative",
    "condition_triggered": "reasoning_traceability, cold_reviewer_clarity, accountability_support—the investigative summary reports facts and supervisor testimony but omits the final analytical step (outcome removed) and critical supporting documents (DRAD file, FMLA records, leave ledgers), preventing reconstruction of how discrimination was ruled out.",
    "compliant_version": "A compliant version would (1) include or append the DRAD accommodation file with all medical documentation and DRAD decisional correspondence, (2) attach or summarize FMLA request forms, medical certifications, and HR's documented basis for any incompleteness finding, (3) provide Complainant's leave balance record as of each contested leave date, (4) restore the final determination section with explicit analysis of each claim against applicable discrimination law, and (5) note whether any alleged HR voicemail recording exists in the investigative file or was ruled inadmissible."
  }
}
